#include <bits/stdc++.h>
using namespace std;

int main() {
    int R, N;
    scanf("%d %d", &R, &N);

    vector<int> best(101, INT_MAX);
    for (int i = 0; i < N; i++) {
        int t, p;
        scanf("%d %d", &t, &p);
        best[t] = min(best[t], p);
    }

    vector<int> prices;
    for (int t = 1; t <= 100; t++) {
        if (best[t] != INT_MAX) prices.push_back(best[t]);
    }

    sort(prices.begin(), prices.end());

    int count = 0;
    for (int p : prices) {
        if (p <= R) {
            R -= p;
            count++;
        } else break;
    }

    printf("%d\n", count);
    return 0;
}
